from packaging.dependency_groups import resolve_dependency_groups as _resolve_dependency_groups


def resolve_dependency_groups(dependency_groups: dict[str, list[str | dict[str, str]]], groups: list[str]) -> list[str]:
    """Resolve dependency groups to a tuple of requirements as strings. dependency_groups: the parsed contents of the [dependency-groups] table from pyproject.toml; groups: the name of the group(s) to resolve, e.g. ['dev'] -> ['pytest>=6', 'ruff']."""
