from typing import List, Iterator, Tuple, Union
from packaging.tags import Tag

def generate_pure_python_tags(python_version: List[int] | None = None) -> List[str]:
    """Generate pure-Python tags compatible with a Python version. python_version: A one- or two-item sequence representing the compatible version of Python, e.g. [3, 9] -> ['py39-none-any', 'py3-none-any', 'py38-none-any', ...]. Defaults to current Python version."""
    if python_version is None:
        # Since we can't import sys, we'll use a default version
        # This mimics the behavior of the real function which uses sys.version_info[:2]
        # For testing purposes, we'll assume Python 3.12 as default
        python_version = [3, 12]

    if not python_version:
        raise ValueError("python_version must contain at least one item")

    # Handle single digit version by padding with 0
    if len(python_version) == 1:
        major = python_version[0]
        minor = 0
    else:
        major = python_version[0]
        minor = python_version[1]

    # Generate all compatible versions from the specified version down to 3.0
    tags = []
    for i in range(major, -1, -1):
        if i == 0:
            # Special case for Python 0.x
            version_str = f"py{i}"
        else:
            # For Python 1.x through 3.x, we need to handle the minor version properly
            if i == major:
                version_str = f"py{i}{minor}" if minor > 0 else f"py{i}"
            else:
                version_str = f"py{i}0"

        tags.append(f"{version_str}-none-any")

    # Remove duplicates and sort properly
    unique_tags = list(dict.fromkeys(tags))  # Preserve order while removing duplicates

    # Sort by version number descending
    def version_key(tag):
        # Extract version part (e.g., "py39", "py3", "py38")
        version_part = tag.split("-")[0]
        # Convert to tuple of integers for sorting
        if version_part.startswith("py"):
            version_nums = version_part[2:]
            if len(version_nums) == 1:
                return (int(version_nums), 0)
            else:
                return (int(version_nums[:-1]), int(version_nums[-1]))
        return (0, 0)

    return sorted(unique_tags, key=version_key, reverse=True)

